import React, { useState } from 'react';
import { useSearchParams } from 'react-router-dom';
import './ResetPasswordPage.css'; // Podés usar el mismo CSS o uno nuevo

const NewPasswordPage = () => {
  const [searchParams] = useSearchParams();
  const token = searchParams.get('token');
  const [newPassword, setNewPassword] = useState('');
  const [message, setMessage] = useState('');

  const handleNewPassword = async (e) => {
    e.preventDefault();
    try {
      const res = await fetch('http://localhost:3000/api/reset-password', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ token, newPassword }),
      });
      const data = await res.json();
      if (res.ok) {
        setMessage('Contraseña actualizada con éxito.');
      } else {
        setMessage(data.error || 'Error al actualizar la contraseña.');
      }
    } catch (error) {
      setMessage('Error de conexión.');
    }
  };

  if (!token) return <p>Token inválido o no proporcionado.</p>;

  return (
    <form onSubmit={handleNewPassword} className="user-form">
      <h2 className="form-title">Nueva Contraseña</h2>

      <label htmlFor="newPassword" className="input-label">Nueva Contraseña</label>
      <input
        id="newPassword"
        type="password"
        placeholder="Nueva contraseña"
        value={newPassword}
        onChange={(e) => setNewPassword(e.target.value)}
        required
        className="input-password"
      />

      <button type="submit" className="submit-button">Actualizar Contraseña</button>
      {message && <p className="message">{message}</p>}
    </form>
  );
};

export default NewPasswordPage;
